import { useMemo, useState } from "react";
import { GraphRail } from "@/shared/ui/layouts/GraphRail";
import { RailGroupHeader } from "@/shared/ui/layouts/RailGroupHeader";
import { RailRow } from "@/shared/ui/layouts/RailRow";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// `groupThemes` vendored (logic unchanged) from `./lib/themes` — the KIT_THEMES-derived pieces dropped
// since this preview takes its theme list as a prop. `KitThemeRecord` inlined as the shape this menu reads.
interface KitThemeRecord { id: string; label: string; base?: "dark" | "light"; tech?: string; vars?: Record<string, string> }
const OTHER_GROUP = "other";
interface ThemeGroup { tech: string; label: string; themes: KitThemeRecord[] }
function groupThemes(records: KitThemeRecord[]): ThemeGroup[] {
  const byTech = new Map<string, KitThemeRecord[]>();
  for (const t of records) {
    const tech = (t.tech ?? "").trim() || OTHER_GROUP;
    const arr = byTech.get(tech);
    if (arr) arr.push(t);
    else byTech.set(tech, [t]);
  }
  const other = byTech.get(OTHER_GROUP);
  if (other && byTech.size > 1) {
    byTech.delete(OTHER_GROUP);
    byTech.set(OTHER_GROUP, other);
  }
  return [...byTech].map(([tech, themes]) => ({ tech, label: tech, themes }));
}

// The real `ThemeSwatch` reads each theme's OWN tokens through `<ThemeScope>` (`@/shared/ui/kit`) — the
// same broken shared/ui/theme/ThemeScope resolution chain behind the known AlgorithmsInspector failure,
// so never cross-import it here. Simplified to the LIVE app tokens (loses per-theme precision, keeps the
// 3-bar chip layout) — same compromise KitThemeCard made for its own preview swatch.
function ThemeSwatch() {
  return (
    <Box style={{ display: "inline-flex", gap: 2, padding: 0, borderRadius: 3 }}>
      <ColorSwatch color="var(--bg-panel)" size={9} />
      <ColorSwatch color="var(--accent)" size={9} />
      <ColorSwatch color="var(--fg)" size={9} />
    </Box>
  );
}

const SAMPLE_THEMES: KitThemeRecord[] = [
  { id: "default", label: "Default", base: "dark", tech: "react" },
  { id: "soft", label: "Soft", base: "dark", tech: "react" },
  { id: "contrast", label: "Contrast", base: "dark", tech: "react" },
  { id: "warm", label: "Warm", base: "dark", tech: "react" },
];

export function ThemesMenu({ themes = SAMPLE_THEMES, activeId = "warm", onSelect = () => {} }: {
  themes?: KitThemeRecord[];
  activeId?: string;
  onSelect?: (id: string) => void;
}) {
  const groups = useMemo(() => groupThemes(themes), [themes]);
  const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
  return (
    <GraphRail
      label="Themes"
      count={themes.length}
      style={{ borderRight: "none", borderLeft: "1px solid var(--border)" }}
    >
      {groups.map((g) => {
        const open = !collapsed[g.tech];
        return (
          <Box key={g.tech} data-tech={g.tech}>
            <RailGroupHeader
              collapsible
              open={open}
              onToggle={() => setCollapsed((c) => ({ ...c, [g.tech]: !c[g.tech] }))}
              count={g.themes.length}
              title={`design group: ${g.label}`}
            >
              {g.label}
            </RailGroupHeader>
            {open && g.themes.map((t) => (
              <RailRow
                key={t.id}
                active={t.id === activeId}
                onClick={() => onSelect(t.id)}
                leading={<ThemeSwatch />}
                trailing={
                  <Text as="span" mono size="xxs" tone="dim" title={`${t.base ?? "dark"} surface`}>
                    {(t.base ?? "dark") === "light" ? "◑" : "◐"}
                  </Text>
                }
                title={`${t.label} — ${t.base ?? "dark"} surface`}
              >
                {t.label}
              </RailRow>
            ))}
          </Box>
        );
      })}
    </GraphRail>
  );
}
